insert into public.site_settings (key, value) values
  ('hero', $json${"eyebrow":"Art, design and more...","titleTop":"אם גם לכם יש קיר","titleEm":"שהוא \"כמעט\"...","subtitle":"אני כאן כדי להפוך אותו למושלם.","primaryCta":"לצפייה ביצירות","secondaryCta":"לתיאום פגישה","image":"images/hero-living-room.jpeg","imageAlt":"סלון מעוצב בגווני לבן ובז׳ עם ספה קרם, שולחן עץ נמוך ויצירת קיר תלת-ממדית לבנה מעל הספה","video":{"webm":"video/hero2.webm","mp4":"video/hero2.mp4","poster":"images/hero2-poster.jpg","description":"סרטון הירו"},"buyBadge":{"text":"לרכישה","whatsappMessage":"היי מיכל, ראיתי את היצירות שלך ואשמח לשמוע איך אפשר לרכוש"}}$json$::jsonb)
insert into public.site_settings (key, value) values
  ('about', $json${"eyebrow":"נעים מאוד","title":"קצת עליי","paragraphs":["אמנית ומעצבת פנים, בעלת תואר שני (M.A.) בחינוך לאמנות. את הדרך שלי אני עושה מתוך אהבה גדולה לחומר, למרחב ולאנשים שחיים בו — ומתוך האמונה שקיר אחד נכון יכול לשנות את כל תחושת הבית.","אני יוצרת יצירות קיר בהתאמה אישית, דו-ממדיות ותלת-ממדיות — \"תכשיטים לקיר\". כל יצירה נולדת מהמרחב שלה: מהאור שנכנס לחדר, מגווני הרהיטים ומהאופי של האנשים הגרים בו.","כל עבודה נעשית בעבודת יד מקצועית, מחומרים יוקרתיים ואיכותיים, עם תשומת לב לכל פרט ולכל מרקם. למעלה משלושים שנות ניסיון בתחום לימדו אותי שהיצירה הנכונה היא זו שנראית כאילו היא הייתה שם מהיום הראשון."],"signature":" ","credentials":["תואר שני (M.A.) בחינוך לאמנות","מעצבת פנים","למעלה מ-30 שנות ניסיון"],"image":"images/michal-portrait.jpg","imageAlt":"מיכל לוי מחייכת — פורטרט","imageFallback":"images/about-portrait.svg","imageFallbackAlt":"יצירת קיר תלת-ממדית בגווני שמנת וחול, בעבודת יד"}$json$::jsonb)
insert into public.site_settings (key, value) values
  ('servicesSection', $json${"eyebrow":"איך אפשר לעבוד יחד","title":"מה אני מציעה","intro":"מיצירה בודדת שנולדת סביב קיר אחד, דרך ליווי עיצובי לחלל שלם ועד סדנאות יצירה לקבוצות ולאירועים — כל מסלול מתחיל באותו מקום: הקשבה למרחב ולאנשים שבו.","outroQuestion":"לא בטוחים איזה מסלול מתאים לכם?","outroCta":"נדבר ונמצא יחד","cardCta":"לפרטים"}$json$::jsonb)
insert into public.site_settings (key, value) values
  ('services', $json$[{"id":"custom","icon":"frame","title":"יצירת קיר בהתאמה אישית","text":"שולחים לי תמונה של החלל או של הקיר, ואני מתאימה את הגודל, הצורה והחומר בדיוק למרחב שלכם — כולל הצעת מחיר מסודרת לפני שמתחילים.","tagline":"יצירה אחת, שנולדת בדיוק עבור הקיר שלכם","intro":["זה הלב של מה שאני עושה. יצירת קיר בהתאמה אישית היא לא תמונה שקונים ותולים, היא אומנות שנוצרת מהמרחב שלה, ולכן היא מתיישבת בו כאילו היא הייתה שם מהיום הראשון.","היצירה יכולה להיות דו-ממדית או תלת-ממדית — תכשיט לקיר: תבליטים, קפלים, מרקמים וקווים שנבנים בשכבות, כולם בעבודת יד ומחומרים יוקרתיים ואיכותיים.","הכול מתחיל בתמונה אחת שאתם שולחים לי. משם אני מתאימה את הגודל, את הצורה, את החומר ואת הגוונים לאור שנכנס לחדר, לרהיטים שכבר יש ולאופי שלכם."],"steps":[{"title":"שולחים תמונה","text":"תמונה של הקיר או של החלל, בוואטסאפ או דרך הטופס באתר. כמה שיותר אור טבעי בתמונה, כך אני רואה טוב יותר את הגוונים האמיתיים."},{"title":"מתאימים יחד","text":"נדבר על הגודל, על הצורה ועל החומר, ועל התחושה שאתם רוצים שהקיר ייתן ביחס לחלל."},{"title":"הצעת מחיר","text":"אתם מקבלים הצעה מסודרת לפני שמתחילים לעבוד, כדי שהכול יהיה ברור משני הצדדים."},{"title":"עבודת היד","text":"היצירה נבנית בסטודיו שלי, שכבה אחר שכבה, בעבודת יד. אני מעדכנת אתכם בדרך."}]},{"id":"interior","icon":"plan","title":"עיצוב פנים מלא","text":"שירותי עיצוב פנים מקצועיים לחלל כולו, מתוך ראייה שלמה של המרחב הביתי — ובתוכה גם התאמת היצירה כך שתשתלב בו באופן טבעי.","tagline":"לא רק הקיר — כל החלל, מתוך ראייה אחת","intro":["אמנות ועיצוב פנים הם שני עולמות שמלווים אותי, וביצירה שלי הם נפגשים ופועלים בסנכרון מושלם.","בעיצוב פנים מלא אני מסתכלת על החלל כשלם: פריסה, פרופורציות, גוונים, חומרים, אור. ומכיוון שאני גם זו שיוצרת את עבודות הקיר, ההתאמה ביניהן לבין החלל היא לא ניחוש — היא חלק מאותה תוכנית."],"steps":[{"title":"הבנת החלל","text":"פגישה והיכרות ועם המרחב."},{"title":"כיוון עיצובי","text":"בונים יחד שפה — גוונים, חומרים ואווירה."},{"title":"תכנון","text":"פריסה, תוכניות, פרופורציות, תאורה ובחירת חומרים, בהתאם להיקף שנסכם עליו."},{"title":"היצירה שמשלימה","text":"ולבסוף יצירת האמנות לקיר שמותאמת לחלל הזה בדיוק."}]},{"id":"homevisit","icon":"home","title":"ביקור בית אישי","text":"מגיעה עד אליכם הביתה (בתשלום), בוחנת את המרחב, ומעצבת ומכינה את היצירה המושלמת במיוחד עבורכם.","tagline":"יש דברים שצריך לראות בעיניים","intro":["תמונה מספרת הרבה, אבל לא הכול. איך האור נופל על הקיר בשעות שונות של היום, כמה גבוהה התקרה, מהו גוון הרצפה, מהי האווירה בחדר ואיזו אווירה אתם רוצים שתהיה — את זה אני קולטת רק כשאני עומדת שם.","בביקור בית אני מגיעה עד אליכם, רואה את המרחב במו עיניי, ומשם מעצבת ומכינה את היצירה המושלמת במיוחד עבורכם. זה המסלול המדויק ביותר, והוא מתאים במיוחד לקירות גדולים, לחללים מורכבים או כשמתלבטים בין כמה אפשרויות."],"note":"ביקור הבית הוא שירות בתשלום. אשמח לתת לכם את כל הפרטים בשיחה.","steps":[{"title":"מתאמים ביקור","text":"קובעים מועד שנוח לכם, ואני מגיעה אליכם הביתה."},{"title":"רואים את החלל","text":"אני מסתכלת על הקיר, על האור, על הגוונים ועל היחס לרהיטים ולחדר כולו."},{"title":"מעצבים על המקום","text":"עוד בבית שלכם אנחנו מדברים על כיוונים, גדלים וחומרים — מול הקיר עצמו."},{"title":"מכינה במיוחד עבורכם","text":"משם היצירה נבנית בסטודיו, מותאמת בדיוק למה שראיתי."}]},{"id":"workshops","icon":"workshop","title":"סדנאות יצירה","text":"סדנאות בהנחייתי לימי הולדת, מסיבות רווקות, ערבי גיבוש ואירועים פרטיים. כל משתתף יוצר בידיו יצירת קיר קטנה ולוקח אותה הביתה.","tagline":"חוויה שכל אחד לוקח איתו הביתה","intro":["אחד הדברים האהובים עליי הוא לראות אנשים שלא חשבו על עצמם כיוצרים מגלים מה הם מסוגלים לעשות. בסדנאות שלי כל משתתף עובד עם החומר בעצמו ומכין יצירת קיר קטנה — ולוקח אותה הביתה בסוף.","הסדנאות מתאימות לימי הולדת, למסיבות רווקות, לערבי גיבוש ולאירועים פרטיים. אין צורך בשום ניסיון קודם, ואין \"נכון או לא נכון\" — אני מלווה כל אחד לפי הקצב שלו.","זו מתנה נפלאה לקבוצה שכבר עשתה הכול: במקום עוד בילוי שנשכח, כולם חוזרים עם משהו שהם יצרו בידיים שלהם."],"note":"מספר המשתתפים, מיקום הסדנה והמחיר נקבעים לפי האירוע — דברו איתי ונתאים.","steps":[{"title":"מספרים לי על האירוע","text":"מה האירוע, בערך כמה אנשים ומה האווירה שאתם מדמיינים."},{"title":"מתאימים סדנה","text":"נסכם יחד את סוג הסדנה , המיקום והמועד שמתאימים לקבוצה שלכם."},{"title":"אני מביאה הכול","text":"החומרים והכלים מגיעים איתי. אתם רק צריכים שולחן וקבוצה במצב רוח טוב."},{"title":"כולם יוצרים","text":"הסדנה כוללת חומרים שאני מביאה. אתם צריכים לבוא רק עם מצב רוח טוב.."}]},{"id":"consult","icon":"chat","title":"ייעוץ ותכנון","text":"שיחת ייעוץ ראשונית להבנת הצרכים, האופי של החלל והכיוון העיצובי — כדי שנצא לדרך עם תמונה ברורה ומדויקת.","tagline":"להתחיל מהמקום הנכון","intro":["לפעמים יודעים שמשהו בקיר לא עובד, אבל לא יודעים מה בדיוק חסר. הייעוץ הוא בשביל השלב הזה — לפני שמזמינים, לפני שמחליטים על גודל, ולפני שקונים חומרים.","בשיחה נבין יחד מה החלל צריך, מה מתאים לאופי שלכם ולאיזה כיוון עיצובי שווה ללכת. גם אם בסוף תחליטו לא להזמין ממני — תצאו עם תמונה ברורה יותר."],"steps":[{"title":"שיחה","text":"מספרים לי מה מטריד ומה אתם מדמיינים, ואני שואלת את השאלות שיחדדו את זה."},{"title":"מסתכלים על החלל","text":"תמונות של הקיר והחדר עוזרות לי לראות את הפרופורציות והגוונים."},{"title":"כיוון ברור","text":"יוצאים עם המלצה לכיוון עיצובי, לגודל ולסוג העבודה שמתאימים לכם."}]}]$json$::jsonb)
insert into public.site_settings (key, value) values
  ('gallerySection', $json${"eyebrow":"עבודת יד","title":"היצירות שלי","intro":"כל יצירה נולדה עבור קיר מסוים אחד, בחומרים יוקרתיים ובעבודת יד מלאה. הציצו ותדמיינו את שלכם.","cta":"לגלריה המלאה","page":{"eyebrow":"פרויקטים","title":"הגלריה","intro":"פיסול, ציור, תבליטים, ועוד — יצירות שנעשו עבור בתים, מבואות וחללים פרטיים. כל אחת מהן נבנתה בעבודת יד, במיוחד עבור הקיר שלה.","allLabel":"הכול","emptyTitle":"הגלריה מתמלאת בימים אלה","emptyText":"התמונות והסרטונים מהפרויקטים האחרונים נמצאים בדרך. בינתיים אשמח לספר לכם על העבודות בשיחה — ולשלוח לכם תמונות ישירות."}}$json$::jsonb)
insert into public.site_settings (key, value) values
  ('stats', $json$[{"value":"30+","label":"שנות ניסיון"},{"value":"עשרות","label":"פרויקטים בהתאמה אישית"},{"value":"100%","label":"עבודת יד"},{"value":"אישי","label":"שירות עד הבית"}]$json$::jsonb)
